// npm install --save-dev prisma dotenv
import "dotenv/config";
import fs from "node:fs";
import { defineConfig } from "prisma/config";

/**
 * Resolve DATABASE_URL_FILE for the Prisma CLI (#145), so
 * `npx prisma migrate deploy` works with a mounted secret. The app itself
 * resolves the same file in src/config/index.ts.
 */
function databaseUrl(): string | undefined {
  const direct = process.env["DATABASE_URL"];
  const file = process.env["DATABASE_URL_FILE"];
  if (direct && file) throw new Error("DATABASE_URL and DATABASE_URL_FILE cannot both be set");
  if (file) {
    const value = fs.readFileSync(file, "utf8").replace(/[\r\n]+$/, "");
    if (!value.trim()) throw new Error("DATABASE_URL_FILE is empty");
    return value;
  }
  return direct;
}

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
    // #147 — `npx prisma migrate reset` and `npx prisma db seed` use this.
    seed: "tsx prisma/seed.ts",
  },
  datasource: {
    url: databaseUrl(),
  },
});
